    id?: string;
    /**
     * 菜单名称
     */
    title?: string;
    /**
     * 路由名称
     */
    name?: string;
    /**
     * 菜单类型（0代表菜单、1代表iframe、2代表外链、3代表按钮）
     */
    menuType?: number;
    /**
     * 父菜单ID
     */
    parentId?: string;
    /**
     * 路由地址
     */
    path?: string;
    /**
     * 组件路径
     */
    component?: string;
    /**
     * 路由参数
     */
    query?: string;
    /**
     * 菜单排序（平台规定只有home路由的rank才能为0，所以后端在返回rank的时候需要从非0开始 点击查看更多）
     */
    sortOrder?: number;
    /**
     * 路由重定向
     */
    redirect?: string;
    /**
     * 菜单图标
     */
    icon?: string;
    /**
     * 右侧菜单图标
     */
    extraIcon?: string;
    /**
     * 菜单状态（1显示 0隐藏）
     */
    visible?: boolean;
    /**
     * 权限标识
     */
    auths?: string;
    /**
     * 进场动画
     */
    enterTransition?: string;
    /**
     * 离场动画
     */
    leaveTransition?: string;
    /**
     * 菜单所属平台（0后台 1前台）
     */
    platformType?: number;
    /**
     * 备注
     */
    remark?: string;
    activePath?: string;
    /**
     * iframe页面地址
     */
    frameSrc?: string;
    /**
     * 内嵌的iframe页面是否开启首次加载动画（0否 1是）
     */
    frameLoading?: boolean;
    /**
     * 路由组件缓存（开启 `true`、关闭 `false`）`可选
     */
    keepAlive?: boolean;
    /**
     * 当前菜单名称或自定义信息禁止添加到标签页（默认`false`）
     */
    hiddenTag?: boolean;
    /**
     * 当前菜单名称是否固定显示在标签页且不可关闭（默认`false`）
     */
    fixedTag?: boolean;
    /**
     * 是否在菜单中显示（默认`true`）`可选
     */
    showLink?: boolean;
    /**
     * 是否显示父级菜单 `可选`
     */
    showParent?: boolean;
    /**
     * 是否删除：0 否，1 是
     */
    deleted?: boolean;
    /**
     * 创建者
     */
    createBy?: string;
    /**
     * 创建时间
     */
    createAt?: string;
    /**
     * 更新者
     */
    updateBy?: string;
    /**
     * 更新时间
     */
